 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 3 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            boxes.append((min(ys), max(ys), min(xs), max(xs)))

    centers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(y0 <= r <= y1 and x0 <= c <= x1 for y0, y1, x0, x1 in boxes):
                centers.append((r, c))

    out = [row[:] for row in grid]
    for r, c in centers:
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in range(max(0, c - 1), min(w, c + 2)):
                if out[y][x] != 2:
                    out[y][x] = 1
    return out
